    moraine:{f:'morainelake',pos:'center 35%',by:'Moraine Lake photo: Terry Ott, CC BY 2.0',u:'https://commons.wikimedia.org/wiki/File:Canada_-_Alberta_-_Banff_National_Park_-_Moraine_Lake.jpg',dark:.24},
